function ModalBox({title,kicker,children,onClose,wide=false}:{title:string,kicker?:string,children:ReactNode,onClose:()=>void,wide?:boolean}){
  const ref=useRef<HTMLDivElement>(null);
  useEffect(()=>{const previous=document.activeElement as HTMLElement;const previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.focus();const handler=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const items=Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]),a[href],input:not([disabled]),select,textarea,[tabindex="0"]')||[]).filter(x=>x.offsetParent!==null);if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',handler);return()=>{document.body.style.overflow=previousOverflow;document.removeEventListener('keydown',handler);previous?.focus();};},[]);
  return <div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)onClose();}}><div className={'modal '+(wide?'wide':'')} role="dialog" aria-modal="true" aria-label={title} ref={ref} tabIndex={-1}><div className="modal-heading"><div>{kicker&&<span className="eyebrow">{kicker}</span>}<h2>{title}</h2></div><button className="icon-btn" aria-label="Close dialog" onClick={onClose}><X/></button></div>{children}</div></div>;
}
