  const [prefs,setPrefs]=useState({min:23,max:35,city:''});const chatEnd=useRef<HTMLDivElement>(null);const photoInput=useRef<HTMLInputElement>(null);
  const me=preview?demoMe:state.me;const matches:Match[]=preview?demoMatches.filter(p=>!sampleBlocks.includes(p.id)):state.matches||[];const requests:Connection[]=preview?sampleRequests.map(r=>r.status==='accepted'?r:{...r,details:undefined,photoShared:false,myPhotoShared:false}):state.requests||[];const accepted=requests.filter(r=>r.status==='accepted');const chat=accepted.find(c=>c.id===chatId)||accepted[0];
