  async function api(action:string,data:any={}){const r=await fetch('/api/app',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...data})});const d:any=await r.json();if(!r.ok)throw Error(d.error||'Please try again.');await load();return d;}
  async function task(run:()=>Promise<void>){if(busy)return;setBusy(true);setError('');try{await run();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
  const go=(v:View)=>{setView(v);setMenu(false);setError('');};
