  async function uploadPhoto(file:File){if(preview){alert('Create your profile to upload a private photo.');return;}if(file.size>5*1024*1024)throw Error('Choose a photo smaller than 5 MB.');if(!['image/jpeg','image/png'].includes(file.type))throw Error('Choose a JPEG or PNG image.');const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');const scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d')!.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Could not process this image.')),'image/jpeg',.9));const r=await fetch('/api/photo',{method:'POST',headers:{'Content-Type':'image/jpeg'},body:blob});const d:any=await r.json();if(!r.ok)throw Error(d.error);await load();alert('Photo uploaded privately. Sharing is off for every connection.');}
  function matchCard(p:Match,i:number){const connection=requests.find(r=>r.other.id===p.id);return <article className="match-card" key={p.id}><div className="card-top"><Avatar theme={i}/><div className="profile-summary"><span className="profile-id">{p.id}</span><h3>{p.age} years <span>· {p.gender}</span></h3><p><MapPin size={13}/>{p.city}, India</p></div><button className="icon-btn small" aria-label={'View '+p.id} onClick={()=>setDetail(p)}><Ellipsis size={20}/></button></div><div className="card-content"><h4>{p.profession}</h4><div className="detail-line"><GraduationCap size={16}/>{p.education}</div><div className="detail-line"><span className="tiny-diamond"/>{p.sect}</div><p className="card-about">{p.about}</p><div className="values">{p.values.slice(0,2).map(v=><span key={v}>{v}</span>)}</div><div className="compatibility"><span className="compat-icon"><HeartHandshake size={15}/></span><span>{shared(p).length?`${shared(p).length} shared ${shared(p).length===1?'value':'values'}`:'Explore your compatibility'}</span><span className="managed"><UsersRound size={13}/>{p.manager==='Self'?'Self-managed':'Family-managed'}</span></div></div><div className="card-footer"><button className="btn secondary" onClick={()=>setDetail(p)}>View profile</button><button className="btn primary" disabled={!!connection} onClick={()=>beginRequest(p)}>{connection?(connection.status==='accepted'?'Connected':connection.status==='pending'?'Requested':'Request closed'):<><Heart size={15}/>Send request</>}</button></div></article>}
